def to_goal(S):
    """raw (...,8) -> R_g^T (x - g) frame"""
    g, gth = S[..., 5:7], S[..., 7]
    c, s = np.cos(gth), np.sin(gth)
    def rot(v):  # R^T v
        v = v - g
        return np.stack([c * v[..., 0] + s * v[..., 1], -s * v[..., 0] + c * v[..., 1]], -1)
    return rot(S[..., 0:2]), rot(S[..., 2:4]), S[..., 4] - gth

