    g, gth = S_t[5:7], S_t[7]; c, s = math.cos(gth), math.sin(gth)
    v = A - (S_t[0:2] if MODE == "goal_rel" else g)
    return np.stack([c * v[..., 0] + s * v[..., 1], -s * v[..., 0] + c * v[..., 1]], -1)

